	x.responseRaw = raw // original POST bytes, including partial/LF/error
	if err != nil || status != http.StatusOK {
		recoveryErr := x.recoverOriginalMutation(ctx, client, origin, "redeem")
		return nil, refused("original_issue_refused", errors.Join(err, recoveryErr))
	}
