func controlRegistrarCanonicalTime(raw string) (time.Time, error) {
	value, err := time.Parse(time.RFC3339Nano, raw)
	if err != nil || value.IsZero() || value.UTC().Format(time.RFC3339Nano) != raw {
		return time.Time{}, refused("original_context_refused", err)
	}
	return value.UTC(), nil
}

func controlRegistrarDecodeRequest(raw []byte) (controlRegistrarRequest, error) {
	var request controlRegistrarRequest
	// Existing exact-key decoder rejects duplicates, case aliases, missing keys,
	// unknown/nested fields and non-null scalar violations, without re-rendering
	// or changing the retained private original request bytes.
	if err := decodePrivateOriginalJSON(raw, &request); err != nil {
		return controlRegistrarRequest{}, err
	}
	if err := controlRegistrarValidateRequest(request); err != nil {
		return controlRegistrarRequest{}, err
	}
	return request, nil
}

func controlRegistrarValidateRequest(request controlRegistrarRequest) error {
	if request.Schema != "original_private_registrar_request_v1" || !capacity.ValidDigest(request.SourceApprovalSHA256) || !capacity.ValidDigest(request.RootPreparationSHA256) {
		return refused("source_registry_refused", nil)
	}
	for _, id := range []string{request.RequestID, request.FactoryRootID, request.CoreOwnerID, request.RegistrarOwnerID} {
		if _, err := uuidParseExact(id); err != nil {
			return refused("source_registry_refused", err)
		}
	}
	if request.CoreOwnerID == request.RegistrarOwnerID {
		return refused("source_registry_refused", nil)
	}
	started, err := controlRegistrarCanonicalTime(request.OriginalContextStartedAt)
	if err != nil {
		return err
	}
	declared, err := controlRegistrarCanonicalTime(request.OriginalContextDeadline)
	if err != nil || !declared.Equal(started.Add(600*time.Second)) {
		return refused("original_context_refused", err)
	}
	phaseBound, err := controlRegistrarCanonicalTime(request.OriginalEffectivePhaseDeadline)
	if err != nil || !phaseBound.After(started) {
		return refused("original_context_refused", err)
	}
	// Cleanup is permitted to join original owners under its separate 150-second
	// bound. It never emits a positive Native observation or renews declaration.
	if request.Phase != "closing" && phaseBound.After(declared) {
		return refused("original_context_refused", nil)
	}
	if request.Phase == "closing" {
		if request.OriginalPhaseCalledAt != nil {
			return refused("original_context_refused", nil)
		}
	} else {
		if request.OriginalPhaseCalledAt == nil {
			return refused("original_context_refused", nil)
		}
		calledAt, e := controlRegistrarCanonicalTime(*request.OriginalPhaseCalledAt)
		if e != nil || calledAt.Before(started) || !calledAt.Before(phaseBound) {
			return refused("original_context_refused", e)
		}
	}
	if request.Phase == "initial" {
		if request.SubjectOwnerID != nil || request.Ordinary {
			return refused("source_registry_refused", nil)
		}
	} else if request.SubjectOwnerID == nil {
		if request.Phase != "closing" {
			return refused("source_registry_refused", nil)
		}
	} else {
		if _, err := uuidParseExact(*request.SubjectOwnerID); err != nil || *request.SubjectOwnerID == request.CoreOwnerID || *request.SubjectOwnerID == request.RegistrarOwnerID {
			return refused("source_registry_refused", err)
		}
	}
	_, _, expected, err := controlRegistrarPhaseFiles(request.Phase, request.Ordinary)
	if err != nil || request.InputFiles == nil || len(request.InputFiles) != len(expected) {
		return refused("source_registry_refused", err)
	}
	for n, actual := range request.InputFiles {
		wanted := expected[n]
		selectorOK := actual.StageSelector == wanted.selector
		if actual.Basename != wanted.basename || !selectorOK || actual.OriginalBytes < 1 || actual.OriginalBytes > bodyLimit || !capacity.ValidDigest(actual.OriginalSHA256) {
			return refused("source_registry_refused", nil)
		}
	}
	return nil
}

func controlRegistrarEncodeRequest(request controlRegistrarRequest, originalInputs [][]byte) ([]byte, error) {
	if err := controlRegistrarValidateRequest(request); err != nil {
		return nil, err
	}
	if len(originalInputs) != len(request.InputFiles) {
		return nil, refused("source_registry_refused", nil)
	}
	for n, input := range originalInputs {
		descriptor := request.InputFiles[n]
		if len(input) != descriptor.OriginalBytes || digest(input) != descriptor.OriginalSHA256 {
			return nil, refused("source_registry_refused", nil)
		}
	}
	raw, err := json.Marshal(request)
	if err != nil || len(raw) == 0 || len(raw) > bodyLimit {
		return nil, refused("source_registry_refused", err)
	}
	decoded, err := controlRegistrarDecodeRequest(raw)
	if err != nil {
		return nil, err
	}
	checked, err := json.Marshal(decoded)
	if err != nil || !bytes.Equal(raw, checked) {
		return nil, refused("source_registry_refused", err)
	}
	return raw, nil
}

