// before the owning method, while its GoReturn is sampled only after it returns.
func controlAssociateOriginalCurrentScope(ctx context.Context, r *OriginalFactoryRealm, p *originalNativePublisher, phase *originalNativePhaseReservation) error {
	ids := [3]string{}
	for n := range ids {
		id, err := newID()
		if err != nil {
			return err
		}
		ids[n] = id
	}
	called := time.Now().UTC()
	err := controlReserveOriginalFactoryOwner(ctx, r, p, phase, ids)
	returned := time.Now().UTC()
	if r == nil || r.control == nil {
		return err
	}
	c := r.control
	c.admissionMu.Lock()
	defer c.admissionMu.Unlock()
	x := c.currentAdmission
	if x == nil || x.ctx != ctx || x.phase != phase || x.publisher != p || !x.scopeReturn.OriginalReturnedAt.IsZero() {
		return errors.Join(err, refused("storage_unknown", nil))
	}
	x.scopeReturn = controlCurrentSourceReturn{"controlReserveOriginalFactoryOwner", r.basal.body.OriginalOwnerID, "host_exterior", called, returned, x.journal.OriginalEffectivePhaseDeadline, "returned", err != nil}
	x.journal.FactoryOwnerEvents[0].OriginalCalledAt = called
	x.journal.FactoryOwnerEvents[0].OriginalReturnedAt = ptr(returned)
	x.journal.FactoryOwnerEvents[0].OriginalErrorPresent = ptr(err != nil)
	x.journal.FactoryOwnerEvents[0].OriginalState = "returned"
	x.cause = errors.Join(x.cause, err, nativeProcessPhase(ctx, p.ledger, called, returned))
	return x.cause
}

