// Source custody, not a native observation/absence proof. The registrar wire
// may be actually empty ONLY for the fixed raw-getdents custody path.
func validateOriginalNativeReceivedFile(h *callHandle, originalFileBody []byte) error {
	return validateOriginalNativeReceivedCustodyFile(h, originalFileBody, false)
}
func validateOriginalNativeReceivedRawGetdentsFile(h *callHandle, originalRaw []byte) error {
	return validateOriginalNativeReceivedCustodyFile(h, originalRaw, true)
}
func validateOriginalNativeReceivedCustodyFile(h *callHandle, originalFileBody []byte, allowEmpty bool) error {
	if h == nil || h.ledger == nil || originalFileBody == nil || (!allowEmpty && len(originalFileBody) == 0) || len(originalFileBody) > bodyLimit {
		return refused("storage_unknown", nil)
	}
	h.mu.Lock()
	defer h.mu.Unlock()
	if !h.closed || h.file == nil || h.closeAt.IsZero() || h.closeErr != nil {
		return refused("storage_unknown", nil)
	}
	var returned []byte
	opens, fstats, closes := 0, 0, 0
	eof := false
	for _, call := range h.unclassified {
		if call.callID == "" || call.returnedAt.IsZero() || !call.private || (call.cause != nil && call.cause != io.EOF) {
			return refused("storage_unknown", nil)
		}
		switch call.operation {
		case "source_file_open":
			opens++
		case "source_file_fstat":
			fstats++
		case "source_file_read":
			if eof || !call.scalarObserved || call.scalar < 0 || call.scalar != int64(len(call.raw)) {
				return refused("storage_unknown", nil)
			}
			returned = append(returned, call.raw...)
			eof = call.cause == io.EOF
		case "source_file_close":
			closes++
		default:
			return refused("storage_unknown", nil)
		}
	}
	if opens != 1 || fstats != 2 || closes != 1 || !eof || !bytes.Equal(returned, originalFileBody) {
		return refused("storage_unknown", nil)
	}
	return nil
}

