// Metadata composition has an acyclic source identity boundary: parent inputs
// are built BEFORE their request InputFiles exist. This grammar checks only
// the six matching headers and captured phase origin; actual producers and
// receivers independently require their genuine Source slot/context custody.
func validateOriginalNativeExportRequestIdentity(request controlRegistrarRequest) error {
	if request.Schema != "original_private_registrar_request_v1" || !capacity.ValidDigest(request.SourceApprovalSHA256) || !capacity.ValidDigest(request.RootPreparationSHA256) {
		return refused("source_registry_refused", nil)
	}
	for _, id := range []string{request.RequestID, request.FactoryRootID, request.CoreOwnerID, request.RegistrarOwnerID} {
		if uuidMust(id) == "" {
			return refused("source_registry_refused", nil)
		}
	}
	if request.CoreOwnerID == request.RegistrarOwnerID {
		return refused("source_registry_refused", nil)
	}
	started, e := controlRegistrarCanonicalTime(request.OriginalContextStartedAt)
	if e != nil {
		return e
	}
	declared, e := controlRegistrarCanonicalTime(request.OriginalContextDeadline)
	if e != nil || !declared.Equal(started.Add(600*time.Second)) {
		return refused("original_context_refused", e)
	}
	bound, e := controlRegistrarCanonicalTime(request.OriginalEffectivePhaseDeadline)
	if e != nil || !bound.After(started) {
		return refused("original_context_refused", e)
	}
	if request.Phase == "closing" {
		if request.OriginalPhaseCalledAt != nil {
			return refused("original_context_refused", nil)
		}
		return nil
	}
	if _, e = controlRegistrarPhaseIndex(request.Phase); e != nil || bound.After(declared) || request.OriginalPhaseCalledAt == nil {
		return refused("original_context_refused", e)
	}
	called, e := controlRegistrarCanonicalTime(*request.OriginalPhaseCalledAt)
	if e != nil || called.Before(started) || !called.Before(bound) {
		return refused("original_context_refused", e)
	}
	return nil
}

