	h, runErr = l.handle()
	if runErr != nil {
		return h, parent, runErr
	}
	_, runErr = ordinaryQMPSourceReturn(ctx, h, "source_audit_artifact_parent_open", false, false, func() (unclassifiedNativeReturn, error) {
		fd, e := unix.Open(i.privateDirectory, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_NONBLOCK|unix.O_CLOEXEC, 0)
		if e == nil {
			h.fd, h.file = fd, os.NewFile(uintptr(fd), "original-qmp-artifact-parent")
		}
		return unclassifiedNativeReturn{scalarObserved: true, scalar: int64(fd)}, e
	})
	if runErr != nil || h.file == nil {
		return h, parent, refused("source_registry_refused", runErr)
	}
	parent, _, runErr = ordinaryQMPSourceStat(ctx, h, "source_audit_artifact_parent_fstat")
	if runErr != nil {
		return h, parent, runErr
	}
