// Sole sealed stdout reader. It serializes complete frame collectors, retaining
// failed/pending actual owners. No generic LF reader or extra goroutine reads
// this endpoint. Its whole-byte cap remains the existing 65536 stdout bound.
func readOriginalSealedWorkerOutput(r *OriginalFactoryRealm, c *originalChild, p *originalNativePublisher, phase *originalNativePhaseReservation) (data []byte, aggregate byteReturn, runErr error) {
	defer close(c.frames)
	defer func() { aggregate.err = runErr }()
	<-c.launchEffectsDone // actual launch memory barrier BEFORE first read
	if c.launchErr != nil || c.startReturn.call == nil || c.startReturn.cause != nil {
		return nil, aggregate, refused("original_start_refused", c.launchErr)
	}
	select {
	case <-r.control.workerBootstrapReady:
	case <-phase.ctx.Done():
		return nil, aggregate, refused("original_context_refused", phase.ctx.Err())
	}
	r.mu.Lock()
	bootstrapCause := r.control.workerBootstrapCause
	bootstrapReturn := r.control.workerBootstrapReturn
	r.mu.Unlock()
	if bootstrapCause != nil || bootstrapReturn.OriginalReturnedAt.IsZero() {
		return nil, aggregate, refused("storage_unknown", bootstrapCause)
	}
	for index, selector := range []string{"basal-owner-worker", "bootstrap-return-worker", "prepared-create-plan", "choice-return", "final-source-audit-worker", "EOF"} {
		if index == 3 {
			select {
			case <-r.control.parentChoiceReady:
			case <-phase.ctx.Done():
				return data, aggregate, refused("original_context_refused", phase.ctx.Err())
			}
			r.mu.Lock()
			phase = r.control.parentChoicePhase
			cause := r.control.parentChoiceCause
			writerReturn := r.control.parentChoiceWriteReturn
			r.mu.Unlock()
			if phase == nil || cause != nil || writerReturn.OriginalReturnedAt.IsZero() {
				return data, aggregate, refused("storage_unknown", cause)
			}
		}
		called := time.Now().UTC()
		read, cause := readOriginalParentWorkerFrame(phase.ctx, c.stdout, phase)
		returned := time.Now().UTC() // actual kernel GoReturn, not read.returnedAt
		bound, _ := phase.ctx.Deadline()
		result := &originalParentWorkerFrameResult{read: read, cause: cause, receiver: controlCurrentSourceReturn{"read_original_parent_worker_frame", p.basal.body.OriginalOwnerID, "host_exterior", called, returned, bound.UTC(), "returned", cause != nil}}
		c.frameMu.Lock()
		c.parentWorkerFrames = append(c.parentWorkerFrames, result)
		c.frameMu.Unlock()
		if read != nil {
			data = append(data, read.prefix...)
			data = append(data, read.raw...)
			for _, row := range read.rows {
				if row.fact.OriginalCount != nil {
					aggregate.count += *row.fact.OriginalCount
				}
				if row.fact.OriginalReturnedAt != nil {
					aggregate.returned = *row.fact.OriginalReturnedAt
				}
				if aggregate.started.IsZero() && row.fact.OriginalCalledAt != nil {
					aggregate.started = *row.fact.OriginalCalledAt
				}
			}
		}
		if aggregate.count > bodyLimit {
			return data, aggregate, refused("original_pipe_refused", cause)
		}
		if index == 5 {
			aggregate.eof = read != nil && len(read.rows) == 1 && read.rows[0].cause == io.EOF && read.rows[0].fact.OriginalCount != nil && *read.rows[0].fact.OriginalCount == 0
			if cause != io.EOF || projectOriginalParentWorkerEOF(read, c) != nil {
				return data, aggregate, refused("original_pipe_refused", cause)
			}
			aggregate.eof, aggregate.sha = true, digest(data)
			return data, aggregate, nativeProcessPhase(phase.ctx, c.stdout.ledger, called, returned)
		}
		if cause != nil {
			return data, aggregate, cause
		}
		var authenticationErr error
		if selector == "final-source-audit-worker" {
			authenticationErr = controlAuthenticateOriginalWorkerFinalSourceAuditFrame(r, c, result)
		} else {
			authenticationErr = controlAuthenticateOriginalParentWorkerFrame(r, c, result, selector)
		}
		if err := authenticationErr; err != nil {
			result.cause = err
			return data, aggregate, err
		}
		if result.selector != selector {
			return data, aggregate, refused("original_pipe_refused", nil)
		}
		c.frameMu.Lock()
		if c.parentFramesBySelector == nil {
			c.parentFramesBySelector = map[string]*originalParentWorkerFrameResult{}
		}
		if c.parentFramesBySelector[selector] != nil {
			c.frameMu.Unlock()
			return data, aggregate, refused("storage_unknown", nil)
		}
		c.parentFramesBySelector[selector] = result
		c.frameMu.Unlock()
		if selector == "final-source-audit-worker" {
			continue
		} // separate private custody, never a Host-stage frame
		select {
		case c.frames <- bytes.Clone(read.raw):
		case <-phase.ctx.Done():
			return data, aggregate, refused("original_context_refused", phase.ctx.Err())
		}
	}
	return data, aggregate, refused("storage_unknown", nil)
}

