	r.control.admissionMu.Lock()
	x := r.control.currentAdmission
	if x == nil || x.preparedFrame != nil || x.phase != result.read.phase {
		r.control.admissionMu.Unlock()
		return refused("storage_unknown", nil)
	}
	x.preparedFrame, x.preparedReceiver = result.read, result.receiver
	x.preparedBody, x.preparedEnvelope = bytes.Clone(result.body), bytes.Clone(result.envelope)
