// Readonly roster/children kernel used by the full original-census join above.
// Its inputs come from validated original publications, not caller flags.
func postStartOriginalThreadRoster(corePID, registrarPID, workerPID int, threads []*originalNativePublication, roster map[string]bool, windows map[int][2]time.Time) error {
	if corePID <= 0 || registrarPID <= 0 || workerPID <= 0 || corePID == registrarPID || corePID == workerPID || registrarPID == workerPID || len(roster) == 0 || len(roster) > 4096 {
		return refused("native_join_refused", nil)
	}
	children := map[int]int{}
	seen := map[string]bool{}
	for _, x := range threads {
		if x == nil || x.thread == nil {
			return refused("native_join_refused", nil)
		}
		t := x.thread
		interval, ok := windows[t.PID]
		key := fmt.Sprintf("%d:%d", t.PID, t.TID)
		if !ok || !roster[key] || seen[key] || t.OriginalThreadStatBeforeRead.OriginalCalledAt.Before(interval[0]) || t.OriginalThreadStatAfterRead.OriginalCloseReturnedAt.After(interval[1]) {
			return refused("native_join_refused", nil)
		}
		seen[key] = true
		for _, child := range t.ChildPIDs {
			if t.PID != corePID || child != registrarPID && child != workerPID || children[child] != 0 {
				return refused("native_join_refused", nil)
			}
			children[child]++
		}
	}
	if len(seen) != len(roster) || children[registrarPID] != 1 || children[workerPID] != 1 || len(children) != 2 {
		return refused("native_join_refused", nil)
	}
	return nil
}

