	if err != nil {
		return h, err
	}
	_, err = currentOriginalAuditCall(ctx, h, "source_directory_open", func() unclassifiedNativeReturn {
		fd, cause := unix.Open(p.installation.privateDirectory, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
		if cause == nil {
			h.fd, h.file = fd, os.NewFile(uintptr(fd), "original-prepared-artifact-parent")
		}
		return unclassifiedNativeReturn{scalarObserved: true, scalar: int64(fd), cause: cause}
	})
