// A new actual terminal namespace/context; earlier Scope/Root ledgers and all
// original counters/handles/envelopes remain unchanged and stay in history.
func controlCreateOriginalTerminalPublisher(ctx context.Context, r *OriginalFactoryRealm, previous *originalNativePublisher) (p *originalNativePublisher, runErr error) {
	if r == nil || r.control == nil || previous == nil || ctx == nil {
		return nil, capacity.ErrHostFactorySourceUnavailable
	}
	c := r.control
	c.publicationMu.Lock()
	r.mu.Lock()
	known := !r.closing && !c.publicationSealed && c.phasePublishers["terminal"] == nil && c.phasePublishers["worker"] == previous && r.nativePhaseContexts["terminal"] == ctx && previous.realm == r && previous.basal == r.basal && previous.rootContext == r.ctx && r.trustedInstallationLocked() == nil
	i, basal, rootCtx := r.installation, r.basal, r.ctx
	scopeRaw, scopeEnvelope, key := bytes.Clone(r.scopeRaw), bytes.Clone(r.records["preauthority-scope"]), bytes.Clone(c.exteriorKey)
	r.mu.Unlock()
	c.publicationMu.Unlock()
	defer clear(key)
	if !known {
		return nil, refused("owner_registration_refused", nil)
	}
	l, err := newOriginalNativeSourceLedger(ctx, i, basal, r.scope.Schema, digest(scopeRaw))
	if err != nil {
		return nil, err
	}
	l.subjects["host_worker"], l.subjects["host_registrar"] = r.scope.CreatorOwnerID, c.registrarExpectedOwnerID
	p, err = newOriginalNativePublisher(rootCtx, i, l, basal, key)
	if err != nil {
		return p, err
	}
	p.realm = r
	c.publicationMu.Lock()
	r.mu.Lock()
	if r.closing || c.publicationSealed || c.phasePublishers["terminal"] != nil {
		r.mu.Unlock()
		c.publicationMu.Unlock()
		return p, refused("owner_registration_refused", nil)
	}
	c.nativePublishers = append(c.nativePublishers, p)
	c.phasePublishers["terminal"] = p
	r.mu.Unlock()
	c.publicationMu.Unlock()
	if err = p.retainOriginalActorHistory(previous); err == nil {
		err = p.retainOriginalBinding(ctx, r.scope.Schema, scopeRaw, scopeEnvelope, nil)
	}
	if err != nil {
		p.mu.Lock()
		p.importFailure = errors.Join(p.importFailure, err)
		p.mu.Unlock()
	}
	return p, errors.Join(err, nativeProcessPhase(ctx, l))
}

// Source assembly input: native_source_audit_owner_linux_fragment.go
// New Source IO owners retain the actual lexical IO context and immutable
// namespace. No previous ledger/context/handle/counter is rebound. Registration
// precedes each owner's first possible file effect, including failed Opens.
func newOriginalPublisherSourceAudit(ctx context.Context, p *originalNativePublisher) (*originalLedger, error) {
	if ctx == nil || p == nil || p.ledger == nil || p.basal == nil || p.sourceProfile == nil || p.ledger.bindingSchema == "original_host_factory_pre_authority_scope_v4" && p.sourceProfile != p.ledger.sourceProfile || p.ledger.ownerID != p.basal.body.OriginalOwnerID || p.ledger.ownerRole != p.basal.body.Role || p.ledger.primitiveSHA != p.basal.sha {
		return nil, capacity.ErrHostFactorySourceUnavailable
	}
	approved, err := originalNativeSourceProfile(p.installation)
	if err != nil || approved == nil {
		return nil, capacity.ErrHostFactorySourceUnavailable
	}
	wanted, e1 := p.sourceProfile.Identity()
	actual, e2 := approved.Identity()
	if errors.Join(e1, e2) != nil || wanted != actual || actual != originalNativeSourceProfileManifestSHA {
		return nil, refused("source_registry_refused", errors.Join(e1, e2))
	}
	audit, err := newLedger(ctx, p.ledger.ownerID, p.ledger.ownerRole, p.ledger.primitiveSHA, p.ledger.bindingSchema, p.ledger.bindingSHA)
	if err != nil {
		return nil, err
	}
	audit.sourceProfile, audit.collection.sourceProfile = p.sourceProfile, p.sourceProfile
	p.mu.Lock()
	p.sourceAuditLedgers = append(p.sourceAuditLedgers, audit)
	p.mu.Unlock()
	if p.realm != nil {
		r := p.realm
		r.mu.Lock()
		if r.control == nil || r.trustedInstallationLocked() != nil {
			r.mu.Unlock()
			return audit, capacity.ErrHostFactorySourceUnavailable
		}
		r.control.sourceAuditOwnerLedgers = append(r.control.sourceAuditOwnerLedgers, audit)
		r.mu.Unlock()
	}
	return audit, nil
}

// Before initial Root inputs have been authenticated the actor's own original
// bootstrap/SourceApproval namespace is the only available file-IO basis.
// Later phases still preserve that acquired directory ancestry; their new file
// audit owns the actual phase context, never a replacement of a.audit.
func (a *originalRegistrarActor) newOriginalSourceAudit(ctx context.Context) (*originalLedger, error) {
	if a == nil || a.audit == nil || a.basal == nil || a.audit.ownerID != a.basal.body.OriginalOwnerID || a.audit.primitiveSHA != a.basal.sha || a.audit.ownerRole != "host_registrar" {
		return nil, capacity.ErrHostFactorySourceUnavailable
	}
	profile, err := originalNativeSourceProfile(a.installation)
	if err != nil || profile == nil {
		return nil, capacity.ErrHostFactorySourceUnavailable
	}
	audit, err := newLedger(ctx, a.audit.ownerID, a.audit.ownerRole, a.audit.primitiveSHA, a.audit.bindingSchema, a.audit.bindingSHA)
	if err != nil {
		return nil, err
	}
	audit.sourceProfile, audit.collection.sourceProfile = profile, profile
	a.sourceAuditLedgers = append(a.sourceAuditLedgers, audit) // actor loop is the sole writer
	return audit, nil
}

// Source assembly input: native_source_graph_linux_fragment.go
// This receiver verifies original Source custody and the original graph before
