	d, ok := ctx.Deadline()
	if e != nil || !ok || !d.Equal(bound) || transfer.request.FactoryRootID != p.root || transfer.cause != nil || transfer.returnedAt.IsZero() || transfer.returnedAt.After(d) || transfer.metadataManifest == nil {
		return refused("original_context_refused", e)
	}
