// Source original-custody grammar only. Every metadata entry is authenticated
// with THIS exact original envelope before it is associated with its CallID.
// No SQL FIRST callback is supplied here and no Native permission is returned.
func (g *originalNativeSourceGraph) authenticateOriginalIO(x originalNativeSignedIO) error {
	entries, e := verifyOriginalNativeProfileStagePurposes(g.installation, g.sourceProfile, x.selector, x.body, x.envelope)
	if e != nil {
		return e
	}
	var chunk model.HostFactoryCallVectorChunk
	if capacity.DecodeHostFactory(x.body, &chunk) != nil {
		if len(entries) != 0 {
			return refused("storage_unknown", nil)
		}
		return nil
	}
	if chunk.BindingSchema != "original_host_factory_pre_authority_scope_v4" {
		if len(entries) != 0 {
			return refused("storage_unknown", nil)
		}
		return nil
	}
	if len(entries) != len(chunk.OriginalCalls) {
		return refused("storage_unknown", nil)
	}
	for _, entry := range entries {
		value := originalNativeAuthenticatedCallPurpose{entry: entry, bindingSchema: chunk.BindingSchema, bindingSHA: chunk.BindingSHA256, ownerRole: chunk.OwnerRole}
		if old, found := g.selectedPurposes[entry.OriginalCallID]; found && old != value {
			return refused("storage_unknown", nil)
		}
		g.selectedPurposes[entry.OriginalCallID] = value
	}
	return nil
}

