	if err != nil {
		return nil, err
	}

	return &originalWorkerIOTransferOwner{publisher: p, audit: audit, anchor: anchor, uid: uint32(p.basal.body.Calls[2].OriginalScalar), gid: uint32(p.basal.body.Calls[3].OriginalScalar), cache: cache}, nil
